// Rewrites one top-level statement so that its load-time work runs later, through
//   deferInit("<chunk>:<offset>", () => { … })
// (runtime/deferred-init.js, generated by tools/emit/readable.mjs), keeping the module-level
// bindings it declares where they are:
//   var/let/const a = x, {b} = y;   ->  let a; let b;  deferInit(k, () => { a = x; ({ b } = y); });
//   class C extends B { … }         ->  let C;  deferInit(k, () => { C = class C extends B { … }; });
//   any other statement S           ->  deferInit(k, () => { S });
// The initialiser text is the original text, unchanged. Declarations become `let` (`var` stays
// `var`): the binding exists from the start of the module as before, and is assigned when the
// deferred initialiser runs. Refused (returned as { error }) when the statement cannot run inside a
// function unchanged: `var` / function declarations inside blocks (they would become local),
// `export`, top-level `await`. (`this` and `import.meta` mean the same inside an arrow function.)
//   import { deferStatement } from './defer.mjs'
//   deferStatement(text, key) -> { code } | { error }
import { parse } from '@babel/parser';

const SKIP = new Set(['loc', 'start', 'end', 'extra', 'leadingComments', 'trailingComments', 'innerComments']);
function* nodes(n, inFn = false) {
  if (!n || typeof n.type !== 'string') return;
  yield [n, inFn];
  const fn = /Function|Method/.test(n.type) && n.type !== 'FunctionDeclaration' || n.type === 'FunctionDeclaration';
  for (const k of Object.keys(n)) {
    if (SKIP.has(k)) continue;
    const v = n[k];
    if (Array.isArray(v)) for (const x of v) yield* nodes(x, inFn || fn);
    else if (v && typeof v.type === 'string') yield* nodes(v, inFn || fn);
  }
}
function patternNames(p, out) {
  if (!p) return out;
  if (p.type === 'Identifier') out.push(p.name);
  else if (p.type === 'ObjectPattern') for (const q of p.properties) patternNames(q.type === 'RestElement' ? q.argument : q.value, out);
  else if (p.type === 'ArrayPattern') for (const q of p.elements) patternNames(q, out);
  else if (p.type === 'AssignmentPattern') patternNames(p.left, out);
  else if (p.type === 'RestElement') patternNames(p.argument, out);
  return out;
}

export function deferStatement(text, key) {
  let ast;
  try { ast = parse(text, { sourceType: 'module', plugins: ['jsx'] }).program; } catch (e) { return { error: 'parse: ' + e.message }; }
  if (ast.body.length !== 1) return { error: 'not one statement' };
  const s = ast.body[0];
  const slice = (n) => text.slice(n.start, n.end);
  for (const [n, inFn] of nodes(s)) {
    if (inFn) continue;
    if (n.type === 'AwaitExpression' || (n.type === 'ForOfStatement' && n.await)) return { error: 'top-level await' };
    if (n !== s && n.type === 'VariableDeclaration' && n.kind === 'var') return { error: 'var inside a block' };
    if (n !== s && n.type === 'FunctionDeclaration') return { error: 'function declaration inside a block' };
  }
  const open = `deferInit(${JSON.stringify(key)}, () => {`;
  if (s.type === 'VariableDeclaration') {
    const kw = s.kind === 'var' ? 'var' : 'let';
    const names = s.declarations.flatMap((d) => patternNames(d.id, []));
    const assigns = s.declarations.filter((d) => d.init).map((d) => (d.id.type === 'ObjectPattern' ? `(${slice(d.id)} = ${slice(d.init)});` : `${slice(d.id)} = ${slice(d.init)};`));
    return { code: `${names.map((n) => `${kw} ${n};`).join('\n')}\n${open}\n${assigns.join('\n')}\n});`, names };
  }
  if (s.type === 'ClassDeclaration') {
    return { code: `let ${s.id.name};\n${open}\n${s.id.name} = ${slice(s)};\n});`, names: [s.id.name] };
  }
  if (s.type === 'ExportDefaultDeclaration' && !/Declaration$/.test(s.declaration.type)) {
    // `export default <expression>`: the value goes to a binding exported as default (a live binding,
    // so importers that read it after the load see the value)
    return { code: `let defaultExport;\n${open}\ndefaultExport = ${slice(s.declaration)};\n});\nexport { defaultExport as default };`, names: ['defaultExport'] };
  }
  if (/^Export|^Import/.test(s.type)) return { error: s.type };
  if (s.type === 'FunctionDeclaration') return { error: 'function declarations are hoisted, never deferred' };
  return { code: `${open}\n${text}\n});`, names: [] };
}
